import React, { useEffect, useState } from "react";
import { updateExamData, getFranchises } from "../api";
import {
    Box,
    Typography,
    Table,
    TableBody,
    TableCell,
    TableContainer,
    TableHead,
    TableRow,
    Paper,
    Button,
    Modal,
    TextField,
} from "@mui/material";

const UserDashboard = () => {
    const [franchises, setFranchises] = useState([]);
    const [open, setOpen] = useState(false); // Modal state
    const [examData, setExamData] = useState({
        examName: "",
        date: "",
        studentsAttended: 0,
        franchiseId: "",
    });

    // Fetch franchises
    useEffect(() => {
        const fetchFranchises = async () => {
            try {
                const data = await getFranchises();
                setFranchises(data);
            } catch (error) {
                console.error("Error fetching franchises:", error.response?.data?.message || error.message);
            }
        };

        fetchFranchises();
    }, []);

    // Handle form input change
    const handleChange = (e) => {
        const { name, value } = e.target;
        setExamData((prev) => ({ ...prev, [name]: value }));
    };

    // Handle update exam data form submission
    const handleUpdateExamData = async () => {
        try {
            await updateExamData(examData.franchiseId, {
                examName: examData.examName,
                date: examData.date,
                studentsAttended: Number(examData.studentsAttended),
            });
            alert("Exam data updated successfully");
            setOpen(false);
        } catch (error) {
            console.error("Error updating exam data:", error.response?.data?.message || error.message);
        }
    };

    return (
        <Box p={3}>
            <Typography variant="h4" gutterBottom>
                User Dashboard
            </Typography>

            {/* Franchises Table */}
            <TableContainer component={Paper}>
                <Table>
                    <TableHead>
                        <TableRow>
                            <TableCell>Franchise Name</TableCell>
                            <TableCell>Location</TableCell>
                            <TableCell>Actions</TableCell>
                        </TableRow>
                    </TableHead>
                    <TableBody>
                        {franchises.map((franchise) => (
                            <TableRow key={franchise._id}>
                                <TableCell>{franchise.name}</TableCell>
                                <TableCell>{franchise.location}</TableCell>
                                <TableCell>
                                    <Button
                                        variant="contained"
                                        color="primary"
                                        onClick={() =>
                                            setExamData((prev) => ({
                                                ...prev,
                                                franchiseId: franchise._id,
                                            })) || setOpen(true)
                                        }
                                    >
                                        Add Exam Data
                                    </Button>
                                </TableCell>
                            </TableRow>
                        ))}
                    </TableBody>
                </Table>
            </TableContainer>

            {/* Modal for updating exam data */}
            <Modal open={open} onClose={() => setOpen(false)}>
                <Box
                    sx={{
                        position: "absolute",
                        top: "50%",
                        left: "50%",
                        transform: "translate(-50%, -50%)",
                        width: 400,
                        bgcolor: "background.paper",
                        borderRadius: 2,
                        boxShadow: 24,
                        p: 4,
                    }}
                >
                    <Typography variant="h6" gutterBottom>
                        Add Exam Data
                    </Typography>
                    <TextField
                        label="Exam Name"
                        name="examName"
                        value={examData.examName}
                        onChange={handleChange}
                        fullWidth
                        margin="normal"
                    />
                    <TextField
                        label="Date"
                        name="date"
                        type="date"
                        value={examData.date}
                        onChange={handleChange}
                        fullWidth
                        margin="normal"
                        InputLabelProps={{ shrink: true }}
                    />
                    <TextField
                        label="Students Attended"
                        name="studentsAttended"
                        type="number"
                        value={examData.studentsAttended}
                        onChange={handleChange}
                        fullWidth
                        margin="normal"
                    />
                    <Button variant="contained" color="primary" onClick={handleUpdateExamData}>
                        Submit
                    </Button>
                </Box>
            </Modal>
        </Box>
    );
};

export default UserDashboard;
